"""冷启动 import torch 的可选优化：把 torch._meta_registrations 惰性化。

默认**关闭**。只有环境变量 XSAI_LAZYMETA 为真（1/true/yes/on）时才装钩子。
镜像里由 init 按 bootargs 打开：

    bootargs 带 ruyi.lazymeta  ->  init 里 export XSAI_LAZYMETA=1
    不带                       ->  什么都不做，本模块只被 import 一下就返回

为什么是它
----------
torch/__init__.py 末尾有一句无条件的 `from torch import _meta_registrations`。这条
import 会连带拉进 torch._prims / torch._refs / torch._decomp.decompositions 整条
子树，并执行 _meta_registrations 里 267 个 @register_meta 加末尾的 activate_meta()
（把 1000+ 个 op 注册进 aten 的 Meta dispatch key）。导入期间 torch 自己并不使用
这个模块，所以"用到再加载"在导入路径上是纯赚。

代价（必须知道）
----------------
延迟加载意味着导入完成时 aten 的 Meta key 上还没有 Python meta kernel。
凡是"在 meta 设备 / FakeTensor 上跑算子"的用法，第一次调用才去补加载；补加载发生
在算子调用内部，部分算子会因此直接失败。实测（qemu-user，74 项 meta 回归）：
基线 6 项失败 -> 惰性化后 22 项失败，新坏 16 项是 conv1d/2d/3d、conv_transpose2d、
adaptive_avg_pool2d、batch_norm、layer_norm、group_norm、embedding、index_select/
gather、max/min/mean、var/std、flip/roll/repeat_interleave、abs/sign/neg、fft、
nn.Sequential(...).to('meta')。全部是**运行时**报
"NotImplementedError: aten::xxx: attempted to run this operator with Meta tensors"，
导入期不报错。回归脚本见 local/ruyi-pytorch/opt/meta_suite.py。

想兜底是兜不了的，两条路都验证过走不通（别再试）：
  1) Library("_","IMPL","Meta").fallback(fn,"Meta") -> C++ 拒绝：
     "Tried to register multiple backend fallbacks for the same dispatch key Meta"
     （MetaFallbackKernel.cpp:23 已经占了这个位置）
  2) 包一层 torch.empty/rand/... 工厂函数做触发 -> 这些在 2.13 是
     builtin_function_or_method，包一层等于给每次建张量加一个解释器帧，不划算

所以只对"确定不碰 meta / fake tensor / 需要 meta 注册的 compile 路径"的负载开。
纯 eager 的建张量、matmul、nn 前向、torch.__version__ 在开启状态下都正常。

关掉 / 回滚
-----------
XSAI_LAZYMETA 不设或设为 0 即可；或者删掉本文件与同目录的 zz_startup_opt.pth。
"""
import os
import sys

_TRUTHY = ("1", "true", "yes", "on")


def _enabled():
    return os.environ.get("XSAI_LAZYMETA", "").strip().lower() in _TRUTHY


def _install():
    import importlib
    import importlib.util
    import types

    lazy_names = tuple(
        x for x in os.environ.get("XSAI_LAZY_MODULES", "torch._meta_registrations").split(",") if x
    )
    debug = os.environ.get("XSAI_LAZYMETA_DEBUG", "").strip().lower() in _TRUTHY
    loading = set()          # 正在惰性加载中的模块名，用来防重入

    def log(msg):
        if debug:
            sys.stderr.write("[zz_startup_opt] %s\n" % msg)

    def _locate(name):
        """定位真模块的 spec。

        不能直接用 importlib.util.find_spec(name)：它发现 sys.modules 里已经有同名
        条目（就是我们的占位模块）且 __spec__ 为 None 时，会直接抛
        ValueError("__spec__ is None")。所以优先用 PathFinder 按父包的 __path__ 找，
        这条路径完全不经过 meta_path，天然绕开本 finder，也不会递归。
        """
        import importlib.machinery

        parent, _, _child = name.rpartition(".")
        path = None
        if parent:
            pkg = sys.modules.get(parent)
            if pkg is None:
                pkg = importlib.import_module(parent)
            path = getattr(pkg, "__path__", None)
        return importlib.machinery.PathFinder.find_spec(name, path)

    class _LazyModule(types.ModuleType):
        """占位模块，属性访问时才把真模块执行出来。

        加载语义刻意对齐 CPython 的 import：先把真模块对象放进 sys.modules 再
        exec_module。这样加载期间发生的循环 import（torch/_decomp/decompositions.py
        里也有 `import torch._meta_registrations`）看到的是"正在进行中的真模块"，
        而不是这个代理——行为和正常导入一致。旧版没有这一步，会在
        torch._subclasses.fake_tensor 路径上撞成循环导入。
        """

        def __init__(self, name):
            super().__init__(name)
            d = self.__dict__
            d["_lz_name"] = name
            d["_lz_real"] = None
            d["__path__"] = []
            d["__doc__"] = "lazy placeholder installed by zz_startup_opt"

        def _lz_load(self):
            d = self.__dict__
            if d["_lz_real"] is not None:
                return d["_lz_real"]
            name = d["_lz_name"]
            if name in loading:
                raise ImportError("zz_startup_opt: recursive lazy load of %s" % name)
            loading.add(name)
            saved = sys.modules.get(name)
            try:
                spec = _locate(name)
                if spec is None or spec.loader is None:
                    raise ImportError("zz_startup_opt: cannot locate %s" % name)
                mod = importlib.util.module_from_spec(spec)
                sys.modules[name] = mod
                log("lazy load: %s" % name)
                try:
                    spec.loader.exec_module(mod)
                except BaseException:
                    sys.modules[name] = saved           # 失败就回滚，不留半成品
                    raise
            finally:
                loading.discard(name)
            parent, _, child = name.rpartition(".")
            if parent:
                p = sys.modules.get(parent)
                if p is not None:
                    setattr(p, child, mod)
            d["_lz_real"] = mod
            return mod

        def __getattr__(self, attr):
            if attr.startswith("_lz_") or (attr.startswith("__") and attr.endswith("__")):
                raise AttributeError(attr)
            return getattr(self._lz_load(), attr)

        def __setattr__(self, attr, value):
            if attr.startswith("_lz_") or (attr.startswith("__") and attr.endswith("__")):
                self.__dict__[attr] = value
            else:
                setattr(self._lz_load(), attr, value)

        def __delattr__(self, attr):
            delattr(self._lz_load(), attr)

        def __dir__(self):
            return dir(self._lz_load())

        def __repr__(self):
            return "<lazy module %r (zz_startup_opt)>" % self.__name__

    class _Loader:
        def create_module(self, spec):
            return None

        def exec_module(self, module):
            # module 已经是 _LazyModule 实例。补上父包属性就行，不执行上游代码。
            parent, _, child = module.__name__.rpartition(".")
            if parent:
                p = sys.modules.get(parent)
                if p is not None:
                    setattr(p, child, module)

    class _Finder:
        def find_spec(self, fullname, path=None, target=None):
            # loading 里的名字正在被 _lz_load 用 importlib.util.find_spec 解析，
            # 此时必须让路给 PathFinder，否则会解析回我们自己，递归成空模块。
            if fullname in loading:
                return None
            if fullname in lazy_names or any(fullname.startswith(n + ".") for n in lazy_names):
                return importlib.util.spec_from_loader(fullname, _Loader(), is_package=True)
            return None

    sys.meta_path.insert(0, _Finder())
    for n in lazy_names:
        sys.modules.setdefault(n, _LazyModule(n))
    log("installed, lazy=%s" % (lazy_names,))


if _enabled():
    try:
        _install()
    except Exception as _exc:            # 装钩子失败绝不能拖垮解释器启动
        sys.stderr.write("[zz_startup_opt] disabled after error: %r\n" % (_exc,))
